#include <cstddef>
#include <iostream>
#include <utility>

class Ledger {
    double* rates_ = nullptr;
    std::size_t n_ = 0;
public:
    explicit Ledger(std::size_t n) : rates_(new double[n]{}), n_(n) {}
    ~Ledger() { delete[] rates_; }

    Ledger(Ledger&& other) noexcept
        : rates_(std::exchange(other.rates_, nullptr)),
          n_(std::exchange(other.n_, 0)) {
        std::cout << "move\n";
    }
    Ledger& operator=(Ledger&& other) noexcept {
        if (this != &other) {
            delete[] rates_;
            rates_ = std::exchange(other.rates_, nullptr);
            n_ = std::exchange(other.n_, 0);
        }
        std::cout << "move=\n";
        return *this;
    }
    Ledger(const Ledger&) = delete;          // focus: moves only
    Ledger& operator=(const Ledger&) = delete;
};

Ledger make_ledger() { return Ledger(1000); }

int main() {
    Ledger a = make_ledger();   // C++17: constructed in place, NO move printed
    Ledger b = std::move(a);    // move
    b = Ledger(500);            // move= from a temporary
}
