#include <iostream>
#include <utility>

void consume(int&)  { std::cout << "lvalue overload\n"; }
void consume(int&&) { std::cout << "rvalue overload\n"; }

template <typename T>
void relay(T&& arg) {
    consume(std::forward<T>(arg));   // category preserved
}

int main() {
    int v = 5;
    relay(v);    // T = int&  -> forward yields int&   -> lvalue overload
    relay(42);   // T = int   -> forward yields int&&  -> rvalue overload
}

